#include "stdafx.h"#include <QbDataTypes_.h>#include <rsuNoNames.h>int RsuHandleInitData( CBase* pObj );int RsuHandleGetParams( CBase* pObj );void RegisterQBstructs(){#undef PNT#define PNT(Class) KNoName::RegisterClassInNames( Class::TypeID, Class::ClassName);#undef  QB_TYPE#define QB_TYPE( a, b, c ) PNT(W_##b)#include <QuickBuilderType.hpp>    KNoName::RegisterInitCBaseCall( RsuHandleInitData );}int RsuHandleInitData( CBase* pObj ){  switch( pObj->ID_CLASS )  {#undef PNT#define PNT(Class) \  case Class::TypeID: \  pObj->size = sizeof(Class); \  memset( ((BYTE*)pObj) + sizeof(CBase), 0, sizeof(Class) - sizeof(CBase) ); \  return 0;#undef  QB_TYPE#define QB_TYPE( a, b, c ) PNT(W_##b)#include <QuickBuilderType.hpp>  };  return -1;}